## 2. Fixtures SOAP (`soap.fixtures.js`)

```javascript
// Exemple avec le service SOAP public : http://www.dneonline.com/calculator.asmx
export const SOAP_CONFIG = {
  url: 'http://www.dneonline.com/calculator.asmx',
  namespace: 'http://tempuri.org/',
};

export const SOAP_ACTIONS = {
  ADD: 'http://tempuri.org/Add',
  SUBTRACT: 'http://tempuri.org/Subtract',
  MULTIPLY: 'http://tempuri.org/Multiply',
  DIVIDE: 'http://tempuri.org/Divide',
};

export const TEST_DATA = {
  addition: {
    intA: 10,
    intB: 5,
    expected: 15,
  },
  subtraction: {
    intA: 10,
    intB: 5,
    expected: 5,
  },
  multiplication: {
    intA: 10,
    intB: 5,
    expected: 50,
  },
  division: {
    intA: 10,
    intB: 5,
    expected: 2,
  },
};
```

