## 3. Tests SOAP (`soap.test.js`)

```javascript
import { t } from 'testcafe';
import SoapHelper from './soap.helper';
import { SOAP_CONFIG, SOAP_ACTIONS, TEST_DATA } from './soap.fixtures';

const soapHelper = new SoapHelper(SOAP_CONFIG.url);

fixture('Tests API SOAP - Calculatrice')
  .page('about:blank');

// ==========================================
// TEST 1 : Addition
// ==========================================
test('SOAP - Addition : 10 + 5 = 15', async t => {
  const { intA, intB, expected } = TEST_DATA.addition;

  const envelope = soapHelper.buildEnvelope('Add', SOAP_CONFIG.namespace, {
    intA,
    intB,
  });

  const response = await soapHelper.sendRequest(SOAP_ACTIONS.ADD, envelope);

  // Vérifier le status HTTP
  await t.expect(response.status).eql(200);

  // Extraire le résultat
  const result = soapHelper.extractValue(
    response.parsed,
    'soap:Envelope.soap:Body.AddResponse.AddResult'
  );

  console.log(`Résultat Addition: ${result}`);

  await t
    .expect(result).notEql(null, 'Le résultat ne doit pas être null')
    .expect(parseInt(result)).eql(expected, `${intA} + ${intB} doit égaler ${expected}`);
});

// ==========================================
// TEST 2 : Soustraction
// ==========================================
test('SOAP - Soustraction : 10 - 5 = 5', async t => {
  const { intA, intB, expected } = TEST_DATA.subtraction;

  const envelope = soapHelper.buildEnvelope('Subtract', SOAP_CONFIG.namespace, {
    intA,
    intB,
  });

  const response = await soapHelper.sendRequest(SOAP_ACTIONS.SUBTRACT, envelope);

  await t.expect(response.status).eql(200);

  const result = soapHelper.extractValue(
    response.parsed,
    'soap:Envelope.soap:Body.SubtractResponse.SubtractResult'
  );

  await t.expect(parseInt(result)).eql(expected);
});

// ==========================================
// TEST 3 : Multiplication
// ==========================================
test('SOAP - Multiplication : 10 * 5 = 50', async t => {
  const { intA, intB, expected } = TEST_DATA.multiplication;

  const envelope = soapHelper.buildEnvelope('Multiply', SOAP_CONFIG.namespace, {
    intA,
    intB,
  });

  const response = await soapHelper.sendRequest(SOAP_ACTIONS.MULTIPLY, envelope);

  await t.expect(response.status).eql(200);

  const result = soapHelper.extractValue(
    response.parsed,
    'soap:Envelope.soap:Body.MultiplyResponse.MultiplyResult'
  );

  await t.expect(parseInt(result)).eql(expected);
});

// ==========================================
// TEST 4 : Division
// ==========================================
test('SOAP - Division : 10 / 5 = 2', async t => {
  const { intA, intB, expected } = TEST_DATA.division;

  const envelope = soapHelper.buildEnvelope('Divide', SOAP_CONFIG.namespace, {
    intA,
    intB,
  });

  const response = await soapHelper.sendRequest(SOAP_ACTIONS.DIVIDE, envelope);

  await t.expect(response.status).eql(200);

  const result = soapHelper.extractValue(
    response.parsed,
    'soap:Envelope.soap:Body.DivideResponse.DivideResult'
  );

  await t.expect(parseInt(result)).eql(expected);
});

// ==========================================
// TEST 5 : Vérification du format de réponse
// ==========================================
test('SOAP - Vérifier la structure de la réponse', async t => {
  const envelope = soapHelper.buildEnvelope('Add', SOAP_CONFIG.namespace, {
    intA: 1,
    intB: 1,
  });

  const response = await soapHelper.sendRequest(SOAP_ACTIONS.ADD, envelope);

  // Vérifier que la réponse est du XML
  await t
    .expect(response.data).contains('<?xml', 'La réponse doit être du XML')
    .expect(response.data).contains('soap:Envelope', 'Doit contenir une enveloppe SOAP')
    .expect(response.data).contains('soap:Body', 'Doit contenir un corps SOAP')
    .expect(response.data).contains('AddResponse', 'Doit contenir une réponse Add');
});

// ==========================================
// TEST 6 : Gestion des erreurs SOAP
// ==========================================
test('SOAP - Gestion erreur : division par zéro', async t => {
  const envelope = soapHelper.buildEnvelope('Divide', SOAP_CONFIG.namespace, {
    intA: 10,
    intB: 0,
  });

  const response = await soapHelper.sendRequest(SOAP_ACTIONS.DIVIDE, envelope);

  // Selon le service, il peut retourner une erreur ou un résultat
  console.log('Réponse division par zéro:', response.data);

  await t
    .expect(response.status).ok('Le statut doit être défini');
});
```

