## 6. Exemple avec authentification WS-Security

```javascript
// soap.auth.helper.js
class SoapAuthHelper extends SoapHelper {
  buildSecureEnvelope(action, namespace, params, credentials) {
    const paramsXml = Object.entries(params)
      .map(([key, value]) => `<${key}>${value}</${key}>`)
      .join('');

    return `<?xml version="1.0" encoding="utf-8"?>
      <soap:Envelope 
        xmlns:soap="http://schemas.xmlsoap.org/soap/envelope/"
        xmlns:wsse="http://docs.oasis-open.org/wss/2004/01/oasis-200401-wss-wssecurity-secext-1.0.xsd">
        <soap:Header>
          <wsse:Security>
            <wsse:UsernameToken>
              <wsse:Username>${credentials.username}</wsse:Username>
              <wsse:Password>${credentials.password}</wsse:Password>
            </wsse:UsernameToken>
          </wsse:Security>
        </soap:Header>
        <soap:Body>
          <${action} xmlns="${namespace}">
            ${paramsXml}
          </${action}>
        </soap:Body>
      </soap:Envelope>`;
  }
}

export default SoapAuthHelper;
```

